/* LearnForge Corporate Website Styles */

:root {
  --primary: #000000;
  --accent: #E6FF32;
  --accent-hover: #d4eb2e;
  --burgundy: #7F2A23;
  --bg: #ffffff;
  --bg-alt: #f7f7f8;
  --text: #111111;
  --text-muted: #555555;
  --text-light: #888888;
  --border: #e5e5e5;
  --radius: 16px;
  --radius-sm: 10px;
  --shadow: 0 4px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.12);
  --max-width: 1200px;
  --transition: 0.25s ease;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
}

a { color: inherit; text-decoration: none; }

img { max-width: 100%; display: block; }

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* Navigation */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(12px);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
}

.logo {
  font-weight: 800;
  font-size: 1.35rem;
  letter-spacing: -0.5px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-mark {
  width: 32px;
  height: 32px;
  background: var(--accent);
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9rem;
}

.nav-links {
  display: flex;
  gap: 32px;
  align-items: center;
}

.nav-links a {
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--text-muted);
  transition: color var(--transition);
}

.nav-links a:hover, .nav-links a.active { color: var(--text); }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: 100px;
  font-weight: 600;
  font-size: 0.95rem;
  cursor: pointer;
  border: none;
  transition: transform var(--transition), background var(--transition), box-shadow var(--transition);
}

.btn:hover { transform: translateY(-1px); }

.btn-primary {
  background: var(--primary);
  color: #fff;
}

.btn-primary:hover { box-shadow: var(--shadow-lg); }

.btn-accent {
  background: var(--accent);
  color: var(--primary);
}

.btn-accent:hover { background: var(--accent-hover); box-shadow: var(--shadow-lg); }

.btn-outline {
  background: transparent;
  color: var(--text);
  border: 1.5px solid var(--border);
}

.btn-outline:hover { border-color: var(--text); }

.btn-sm { padding: 8px 18px; font-size: 0.88rem; }

/* Hero */
.hero {
  padding: 80px 0 60px;
  overflow: hidden;
}

.hero-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.hero-text h1 {
  font-size: clamp(2.2rem, 4.5vw, 3.4rem);
  line-height: 1.1;
  font-weight: 800;
  letter-spacing: -1px;
  margin-bottom: 20px;
}

.hero-text p {
  font-size: 1.15rem;
  color: var(--text-muted);
  margin-bottom: 32px;
  max-width: 520px;
}

.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

.hero-visual {
  position: relative;
  border-radius: var(--radius);
  background: var(--bg-alt);
  padding: 24px;
  min-height: 380px;
  display: flex;
  flex-direction: column;
}

.hero-tabs {
  display: inline-flex;
  background: #fff;
  border-radius: 100px;
  padding: 4px;
  box-shadow: var(--shadow);
  margin-bottom: 20px;
  align-self: flex-start;
}

.hero-tab {
  padding: 8px 18px;
  border-radius: 100px;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  background: transparent;
  color: var(--text-muted);
  transition: all var(--transition);
}

.hero-tab.active {
  background: var(--primary);
  color: #fff;
}

.hero-preview {
  flex: 1;
  border-radius: var(--radius-sm);
  background: #fff;
  box-shadow: var(--shadow);
  overflow: hidden;
  position: relative;
}

.hero-preview-panel {
  position: absolute;
  inset: 0;
  opacity: 0;
  transform: translateX(12px);
  transition: opacity 0.3s ease, transform 0.3s ease;
  pointer-events: none;
  padding: 24px;
}

.hero-preview-panel.active {
  opacity: 1;
  transform: translateX(0);
  pointer-events: auto;
}

/* Mock UI for preview panels */
.mock-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}

.mock-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--accent);
}

.mock-line {
  height: 10px;
  border-radius: 4px;
  background: var(--bg-alt);
  margin-bottom: 10px;
}

.mock-line.short { width: 60%; }

.mock-card {
  border-radius: var(--radius-sm);
  background: var(--bg-alt);
  padding: 16px;
  margin-bottom: 12px;
}

.mock-card-title {
  height: 14px;
  width: 70%;
  background: #ddd;
  border-radius: 4px;
  margin-bottom: 8px;
}

.mock-card-body {
  height: 10px;
  width: 90%;
  background: #e5e5e5;
  border-radius: 4px;
  margin-bottom: 6px;
}

.mock-progress {
  height: 8px;
  border-radius: 4px;
  background: #e5e5e5;
  margin-top: 10px;
  overflow: hidden;
}

.mock-progress-bar {
  height: 100%;
  width: 65%;
  background: var(--accent);
  border-radius: 4px;
}

/* Stats bar */
.stats-bar {
  background: var(--primary);
  color: #fff;
  padding: 48px 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  text-align: center;
}

.stat-number {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--accent);
  line-height: 1;
  margin-bottom: 8px;
}

.stat-label {
  font-size: 0.95rem;
  color: rgba(255,255,255,0.75);
}

/* Section base */
.section {
  padding: 80px 0;
}

.section-alt { background: var(--bg-alt); }

.section-header {
  max-width: 640px;
  margin-bottom: 48px;
}

.section-header h2 {
  font-size: clamp(1.8rem, 3.5vw, 2.6rem);
  font-weight: 800;
  letter-spacing: -0.5px;
  line-height: 1.15;
  margin-bottom: 14px;
}

.section-header p {
  font-size: 1.05rem;
  color: var(--text-muted);
}

/* Cards */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}

.card {
  background: #fff;
  border-radius: var(--radius);
  padding: 28px;
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  margin-bottom: 18px;
}

.card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 10px;
}

.card p {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* Why Choose Us Tabs */
.tabs-nav {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 32px;
}

.tab-pill {
  padding: 10px 20px;
  border-radius: 100px;
  border: 1.5px solid var(--border);
  background: #fff;
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  transition: all var(--transition);
}

.tab-pill:hover { border-color: var(--text-muted); }

.tab-pill.active {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

.feature-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
}

.feature-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  background: #fff;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow);
}

.feature-check {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 0.75rem;
}

/* Testimonials Carousel */
.testimonials-wrap {
  position: relative;
}

.testimonials-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  padding-bottom: 8px;
  -webkit-overflow-scrolling: touch;
}

.testimonials-track::-webkit-scrollbar { height: 6px; }
.testimonials-track::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

.testimonial-card {
  min-width: 340px;
  max-width: 340px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: var(--radius);
  padding: 28px;
  box-shadow: var(--shadow);
}

.testimonial-quote {
  font-size: 1rem;
  line-height: 1.6;
  margin-bottom: 20px;
  color: var(--text);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 14px;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.9rem;
}

.testimonial-name {
  font-weight: 700;
  font-size: 0.95rem;
}

.testimonial-role {
  font-size: 0.85rem;
  color: var(--text-light);
}

.testimonial-tag {
  display: inline-block;
  margin-top: 6px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--burgundy);
  background: rgba(127,42,35,0.08);
  padding: 4px 10px;
  border-radius: 100px;
}

.carousel-controls {
  display: flex;
  gap: 12px;
  margin-top: 24px;
  justify-content: flex-end;
}

.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1.5px solid var(--border);
  background: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}

.carousel-btn:hover {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

/* Pricing */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
}

.pricing-card {
  background: #fff;
  border-radius: var(--radius);
  padding: 28px;
  box-shadow: var(--shadow);
  text-align: center;
  transition: transform var(--transition);
}

.pricing-card:hover { transform: translateY(-4px); }

.pricing-card.featured {
  border: 2px solid var(--accent);
  position: relative;
}

.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 14px;
  border-radius: 100px;
}

.pricing-name {
  font-weight: 700;
  font-size: 1.1rem;
  margin-bottom: 8px;
}

.pricing-price {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 4px;
}

.pricing-price span {
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--text-muted);
}

.pricing-note {
  font-size: 0.85rem;
  color: var(--text-light);
  margin-bottom: 20px;
}

.pricing-features {
  list-style: none;
  text-align: left;
  margin-bottom: 24px;
}

.pricing-features li {
  padding: 6px 0;
  font-size: 0.9rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Integrations */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 16px;
}

.integration-item {
  background: #fff;
  border-radius: var(--radius-sm);
  padding: 18px 12px;
  text-align: center;
  box-shadow: var(--shadow);
  font-weight: 600;
  font-size: 0.88rem;
  transition: transform var(--transition);
}

.integration-item:hover { transform: translateY(-3px); }

.integration-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--bg-alt);
  margin: 0 auto 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
}

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: 22px 0;
  font-size: 1.05rem;
  font-weight: 600;
  background: none;
  border: none;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color var(--transition);
}

.faq-question:hover { color: var(--burgundy); }

.faq-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  transition: transform var(--transition), background var(--transition);
  flex-shrink: 0;
  margin-left: 12px;
}

.faq-item.open .faq-icon {
  transform: rotate(45deg);
  background: var(--accent);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 22px;
}

.faq-answer p {
  color: var(--text-muted);
  font-size: 0.97rem;
  line-height: 1.6;
}

/* Steps */
.steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 24px;
  counter-reset: step;
}

.step {
  position: relative;
  padding: 28px;
  background: #fff;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.step::before {
  counter-increment: step;
  content: counter(step);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.9rem;
  margin-bottom: 16px;
}

.step h3 {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 10px;
}

.step p {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* CTA Banner */
.cta-banner {
  background: var(--primary);
  color: #fff;
  padding: 80px 0;
  text-align: center;
}

.cta-banner h2 {
  font-size: clamp(1.8rem, 3.5vw, 2.6rem);
  font-weight: 800;
  margin-bottom: 16px;
  letter-spacing: -0.5px;
}

.cta-banner p {
  font-size: 1.1rem;
  color: rgba(255,255,255,0.75);
  margin-bottom: 32px;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

/* Footer */
.footer {
  background: #0a0a0a;
  color: rgba(255,255,255,0.7);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 40px;
  margin-bottom: 48px;
}

.footer-col h4 {
  color: #fff;
  font-size: 0.9rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 18px;
}

.footer-col a {
  display: block;
  font-size: 0.9rem;
  padding: 6px 0;
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--accent); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  font-size: 0.85rem;
  color: rgba(255,255,255,0.5);
}

/* Tools grid */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 16px;
}

.tool-item {
  background: #fff;
  border-radius: var(--radius-sm);
  padding: 18px;
  text-align: center;
  box-shadow: var(--shadow);
  font-weight: 600;
  font-size: 0.9rem;
  transition: transform var(--transition);
}

.tool-item:hover { transform: translateY(-3px); }

.tool-icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: var(--accent);
  margin: 0 auto 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}

/* Two column layouts */
.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.two-col.reverse { direction: rtl; }
.two-col.reverse > * { direction: ltr; }

.visual-box {
  border-radius: var(--radius);
  background: var(--bg-alt);
  padding: 32px;
  min-height: 320px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

/* Spotlight cards */
.spotlight-card {
  background: #fff;
  border-radius: var(--radius);
  padding: 28px;
  box-shadow: var(--shadow);
  transition: transform var(--transition);
}

.spotlight-card:hover { transform: translateY(-4px); }

.spotlight-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.spotlight-card p {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* Resources */
.resource-card {
  background: #fff;
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  transition: transform var(--transition);
}

.resource-card:hover { transform: translateY(-3px); }

.resource-card h3 {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.resource-card p {
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* Social proof / trust bar */
.trust-bar {
  text-align: center;
  padding: 40px 0;
}

.trust-bar p {
  font-size: 0.9rem;
  color: var(--text-light);
  margin-bottom: 20px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.trust-logos {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 40px;
  flex-wrap: wrap;
}

.trust-logo {
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--text-light);
  opacity: 0.7;
}

/* Responsive */
@media (max-width: 900px) {
  .hero-inner, .two-col {
    grid-template-columns: 1fr;
  }
  .stats-grid { grid-template-columns: 1fr; gap: 32px; }
  .nav-links { display: none; }
  .testimonial-card { min-width: 280px; max-width: 280px; }
}

@media (max-width: 600px) {
  .section { padding: 56px 0; }
  .hero { padding: 48px 0 40px; }
  .card-grid { grid-template-columns: 1fr; }
  .pricing-grid { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
}

/* Utilities */
.text-center { text-align: center; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.w-full { width: 100%; }

/* LearnForge Corporate Website Interactions */

(function () {
  'use strict';

  // --- Hero tab switch ---
  function initHeroTabs() {
    const tabs = document.querySelectorAll('.hero-tab');
    const panels = document.querySelectorAll('.hero-preview-panel');
    if (!tabs.length) return;

    tabs.forEach((tab) => {
      tab.addEventListener('click', () => {
        const target = tab.dataset.target;
        tabs.forEach((t) => t.classList.remove('active'));
        tab.classList.add('active');
        panels.forEach((p) => {
          p.classList.toggle('active', p.dataset.panel === target);
        });
      });
    });
  }

  // --- Why Choose Us tabs ---
  function initFeatureTabs() {
    const nav = document.querySelector('.tabs-nav');
    if (!nav) return;
    const pills = nav.querySelectorAll('.tab-pill');
    const contents = document.querySelectorAll('.tab-content');

    pills.forEach((pill) => {
      pill.addEventListener('click', () => {
        const target = pill.dataset.tab;
        pills.forEach((p) => p.classList.remove('active'));
        pill.classList.add('active');
        contents.forEach((c) => {
          c.classList.toggle('active', c.dataset.content === target);
        });
      });
    });
  }

  // --- FAQ Accordions ---
  function initAccordions() {
    document.querySelectorAll('.faq-question').forEach((btn) => {
      btn.addEventListener('click', () => {
        const item = btn.closest('.faq-item');
        const wasOpen = item.classList.contains('open');

        // Close siblings if desired (single-open behavior)
        const parent = item.closest('.faq-list');
        if (parent && parent.dataset.single === 'true') {
          parent.querySelectorAll('.faq-item.open').forEach((sib) => {
            if (sib !== item) sib.classList.remove('open');
          });
        }

        item.classList.toggle('open', !wasOpen);
      });
    });
  }

  // --- Testimonials Carousel ---
  function initCarousels() {
    document.querySelectorAll('.carousel-controls').forEach((controls) => {
      const track = controls.closest('.testimonials-wrap')?.querySelector('.testimonials-track');
      if (!track) return;
      const prev = controls.querySelector('.carousel-prev');
      const next = controls.querySelector('.carousel-next');
      const card = track.querySelector('.testimonial-card');
      if (!card) return;
      const scrollAmount = card.offsetWidth + 24; // gap

      prev?.addEventListener('click', () => {
        track.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
      });
      next?.addEventListener('click', () => {
        track.scrollBy({ left: scrollAmount, behavior: 'smooth' });
      });
    });
  }

  // --- Product Demo Accordion ---
  function initDemoAccordion() {
    const btn = document.querySelector('.demo-toggle');
    const panel = document.querySelector('.demo-panel');
    if (!btn || !panel) return;
    btn.addEventListener('click', () => {
      const open = panel.classList.toggle('open');
      btn.setAttribute('aria-expanded', String(open));
    });
  }

  // --- Scroll reveal ---
  function initScrollReveal() {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('revealed');
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.1 }
    );
    document.querySelectorAll('.reveal').forEach((el) => observer.observe(el));
  }

  // --- Mobile nav toggle ---
  function initMobileNav() {
    const toggle = document.querySelector('.nav-toggle');
    const links = document.querySelector('.nav-links');
    if (!toggle || !links) return;
    toggle.addEventListener('click', () => {
      links.classList.toggle('open');
    });
  }

  document.addEventListener('DOMContentLoaded', () => {
    initHeroTabs();
    initFeatureTabs();
    initAccordions();
    initCarousels();
    initDemoAccordion();
    initScrollReveal();
    initMobileNav();
  });
})();

