import html.parser

class Validator(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.stack = []
        self.self_closing = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.self_closing:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.self_closing:
            return
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        else:
            self.errors.append(f'Unexpected </{tag}>')
    def close(self):
        super().close()
        if self.stack:
            self.errors.append(f'Unclosed tags: {self.stack}')

import os
for f in sorted(os.listdir('.')):
    if f.endswith('.html'):
        v = Validator()
        with open(f) as fh:
            v.feed(fh.read())
        v.close()
        status = 'OK' if not v.errors else 'ERR: ' + '; '.join(v.errors)
        print(f'{f}: {status}')
